(() => {

  const text = ($json.article_text || '').trim();
  const lower = text.toLowerCase();

  // Empty / too short
  if (text.length < 200) {
    return false;
  }

  // Only inspect the beginning of the page.
  // This avoids rejecting a real article just because
  // some footer mentions JavaScript/cookies.
  const beginning = lower.slice(0, 1200);

  const blockedSignals = [
    'access denied',
    'verify you are human',
    'verify that you are not a robot',
    'javascript is disabled',
    'enable javascript and cookies',
    'checking your browser',
    'captcha',
    'request blocked',
    'forbidden',
    'just a moment'
  ];

  const blocked = blockedSignals.some(
    signal => beginning.includes(signal)
  );

  return !blocked;

})()
}}

