parameters.jsCode:
const originalItems = $('Remove Duplicates').all();
const processedItems = $input.all();

const processedMap = new Map();

for (const item of processedItems) {
  if (item.json.URL && item.json.Processed_At) {
    processedMap.set(
      String(item.json.URL),
      item.json.Processed_At
    );
  }
}

const cutoff = DateTime.now().minus({ hours: 48 });

const output = [];

for (const item of originalItems) {

  const url = String(item.json.URL || '');
  const processedAt = processedMap.get(url);

  // Never processed before
  if (!processedAt) {
    output.push({
      json: { ...item.json }
    });
    continue;
  }

  const processedDate = DateTime.fromFormat(
    processedAt,
    'M/d/yyyy H:mm:ss'
  );

  // Invalid date - allow processing
  if (!processedDate.isValid) {
    output.push({
      json: { ...item.json }
    });
    continue;
  }

  // Only process if older than 48 hours
  if (processedDate < cutoff) {
    output.push({
      json: { ...item.json }
    });
  }
}

return output;
